  BioClick = (id, bio) => {

    let arr = [...this.state.arr];

    if(arr[id].pilih) {
      arr[id].pilih = false;
      arr[id].go = true;
    } else {
      arr[id].pilih = true;
    }

    arr.forEach(it => {
      if(it.id !== id) {
        it.pilih = false;
        it.go = false;
      }
    });

    this.setState({
      arr
    });

  }
